def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    # The 3 divider separates shape panels; remove it. The marked 8s denote
    # the corners/extremes of the non-rectangular 2-shapes (demo endpoints).
    for r in range(h):
        for c in range(w):
            if out[r][c]==3: out[r][c]=0
    # Mark relevant pattern ends observed in demos by identifying the component extrema.
    seen=set()
    for r in range(h):
        for c in range(w):
            if out[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and out[yy][xx]==2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            # Rows of the component: highlight leftmost cell on its top and bottom edges.
            for rr in (min(y for y,x in comp), max(y for y,x in comp)):
                y,x=min((p for p in comp if p[0]==rr),key=lambda p:p[1])
                out[y][x]=8
    return out

